<second_data>
To integrate an e-commerce site with Salesforce Commerce Cloud (SFCC), you can use the SFCC APIs, specifically the Shop API, to interact with the platform. Here's a TypeScript example using the `axios` library to make HTTP requests and the `jsforce` library to authenticate with Salesforce. First, install the required libraries:

```bash
npm install axios jsforce
```

Now, create a TypeScript file (e.g., `sfcc-integration.ts`) and add the following code:

```typescript
import axios from 'axios';
import { Connection, SfApi } from 'jsforce';

// Replace these values with your SFCC credentials and environment details
const SFCC_USERNAME = 'your_sfcc_username';
const SFCC_PASSWORD = 'your_sfcc_password';
const SFCC_SECURITY_TOKEN = 'your_sfcc_security_token';
const SFCC_INSTANCE_URL = 'your_sfcc_instance_url'; // e.g., https://your-instance.demandware.net
const SFCC_SITE_ID = 'your_sfcc_site_id';

// Function to authenticate with SFCC
async function authenticate(): Promise<SfApi> {
 const conn = new Connection({
    loginUrl: SFCC_INSTANCE_URL,
  });

 await conn.login(SFCC_USERNAME, `${SFCC_PASSWORD}${SFCC_SECURITY_TOKEN}`);

  return conn.sfapi;
}

// Function to get products from SFCC
async function getProducts(sfapi: SfApi): Promise<any[]> {
 const response = await sfapi.request(`/s/-/dw/shop/v18_1/products`, {
    method: 'GET',
    params: {
      site_id: SFCC_SITE_ID,
      page_size: 100,
    },
  });

  return response.data.data;
}

// Function to create an order in SFCC
async function createOrder(sfapi: SfApi, orderData: any): Promise<any> {
 const response = await sfapi.request(`/s/-/dw/shop/v18_1/orders`, {
    method: 'POST',
    data: orderData,
  });

  return response.data;
}

// Example usage
(async () => {
 try {
    const sfapi = await authenticate();

    // Get products
    const products = await getProducts(sfapi);
    console.log('Products:', products);

    // Create an order (replace this with your order data)
    const orderData = {
      line_items: [
        {
          product_id: 'product_id_1',
          quantity: 1,
        },
      ],
      shipping_address: {
        first_name: 'John',
        last_name: 'Doe',
        address1: '123 Main St',
        city: 'San Francisco',
        state_code: 'CA',
        postal_code: '94105',
        country_code: 'US',
      },
    };

    const order = await createOrder(sfapi, orderData);
    console.log('Order:', order);
  } catch (error) {
    console.error('Error:', error);
  }
})();
```

Replace the placeholders with your SFCC credentials and environment details. This example demonstrates how to authenticate, get products, and create an order using the SFCC Shop API. You can extend this example to include other API endpoints and functionality as needed.
