{
    private $sqsClient;

    public function __construct($region, $accessKey, $secretKey)
    {
        $this->sqsClient = new SqsClient([
            'region' => $region,
            'version' => 'latest',
            'credentials' => [
                'key' => $accessKey,
                'secret' => $secretKey,
            ],
        ]);
