library(tidyverse)

# Define the format for sHSADLH
sHSADLH_format <- c("0 Independent", "1 Supervision required", "2 Limited impairment",
                    "3 Extensive Assistance Required - 1", "4 Extensive Assistance Required - 2",
                    "5 Dependent", "6 Total Dependence")

# Define the function to calculate sHSADLH
calculate_sHSADLH <- function(iG2b, iG2e, iG2h, iG2j) {
  # Check if all variables have valid values
  if (all(c(iG2b, iG2e, iG2h, iG2j) %in% c(0:6, 8))) {
    # Compute ADL Hierarchy
    if (all(c(iG2b, iG2e, iG2h, iG2j) %in% c(6, 8))) {
      sHSADLH <- 6
    } else if (any(c(iG2e, iG2j) %in% c(6, 8))) {
      sHSADLH <- 5
    } else if (any(c(iG2e, iG2j) %in% c(4, 5))) {
      sHSADLH <- 4
    } else if (any(c(iG2b, iG2h) > 3)) {
      sHSADLH <- 3
    } else if (any(c(iG2b, iG2e, iG2h, iG2j) == 3)) {
      sHSADLH <- 2
    } else if (any(c(iG2b, iG2e, iG2h, iG2j) == 2)) {
      sHSADLH <- 1
    } else if (all(c(iG2b, iG2e, iG2h, iG2j) %in% c(0, 1))) {
      sHSADLH <- 0
    } else {
      sHSADLH <- NA
    }
  } else {
    sHSADLH <- NA
  }

  # Label sHSADLH
  sHSADLH <- factor(sHSADLH, levels = 0:6, labels = sHSADLH_format)

  return(sHSADLH)
}

# Example usage:
df <- tibble(iG2b = c(0, 1, 2, 3, 4, 5, 6, 8),
             iG2e = c(0, 1, 2, 3, 4, 5, 6, 8),
             iG2h = c(0, 1, 2, 3, 4, 5, 6, 8),
             iG2j = c(0, 1, 2, 3, 4, 5, 6, 8))

df <- df %>%
  mutate(sHSADLH = map2_chr(iG2b, iG2e, iG2h, iG2j, calculate_sHSADLH))
```

